// =====================================================
// SOLUCIONES COLINA — Almacenamiento Local Seguro
// Usa @capacitor/preferences (nativo) + cifrado AES-256
// Los datos NUNCA salen del dispositivo
// =====================================================
import { Preferences } from '@capacitor/preferences'
import { cifrar, descifrar } from './encryptionService'
import type { FacturaDetalle, NegocioInfo } from '../types'

// ── Claves de almacenamiento ───────────────────────
const KEYS = {
  PERFIL:        'sc_perfil',
  FACTURAS:      'sc_facturas',
  PIN_HASH:      'sc_pin_hash',
  PIN_SAL:       'sc_pin_sal',
  SESION_TOKEN:  'sc_sesion',
  INSTALADO:     'sc_instalado',
  SESION_TS:     'sc_sesion_ts',
} as const

const TIMEOUT_SESION_MS = 5 * 60 * 1000  // 5 minutos

// ── Perfil / Empresa ──────────────────────────────

export interface PerfilEmpresa {
  id: string
  nombre: string
  nit: string
  dv: string
  correo: string
  telefono?: string
  direccion?: string
  ciudad?: string
  creadoEn: string
}

export async function guardarPerfil(perfil: PerfilEmpresa, pin: string, sal: string): Promise<void> {
  const cifrado = await cifrar(perfil, pin, sal)
  await Preferences.set({ key: KEYS.PERFIL, value: cifrado })
}

export async function cargarPerfil(pin: string, sal: string): Promise<PerfilEmpresa | null> {
  const { value } = await Preferences.get({ key: KEYS.PERFIL })
  if (!value) return null
  try {
    return await descifrar<PerfilEmpresa>(value, pin, sal)
  } catch {
    return null
  }
}

// ── Facturas ──────────────────────────────────────

export async function guardarFacturas(facturas: FacturaDetalle[], pin: string, sal: string): Promise<void> {
  const cifrado = await cifrar(facturas, pin, sal)
  await Preferences.set({ key: KEYS.FACTURAS, value: cifrado })
}

export async function cargarFacturas(pin: string, sal: string): Promise<FacturaDetalle[]> {
  const { value } = await Preferences.get({ key: KEYS.FACTURAS })
  if (!value) return []
  try {
    return await descifrar<FacturaDetalle[]>(value, pin, sal)
  } catch {
    return []
  }
}

export async function agregarFactura(factura: FacturaDetalle, pin: string, sal: string): Promise<void> {
  const actuales = await cargarFacturas(pin, sal)
  // Evitar duplicados por numeroFactura
  const sinDuplicado = actuales.filter(f => f.id !== factura.id)
  await guardarFacturas([factura, ...sinDuplicado], pin, sal)
}

export async function eliminarFactura(facturaId: string, pin: string, sal: string): Promise<void> {
  const actuales = await cargarFacturas(pin, sal)
  const filtradas = actuales.filter(f => f.id !== facturaId)
  await guardarFacturas(filtradas, pin, sal)
}

// ── Sesión ────────────────────────────────────────

export async function iniciarSesion(pinHash: string): Promise<void> {
  await Preferences.set({ key: KEYS.SESION_TOKEN, value: pinHash })
  await Preferences.set({ key: KEYS.SESION_TS, value: Date.now().toString() })
}

export async function cerrarSesion(): Promise<void> {
  await Preferences.remove({ key: KEYS.SESION_TOKEN })
  await Preferences.remove({ key: KEYS.SESION_TS })
}

export async function sesionActiva(): Promise<boolean> {
  const { value: token } = await Preferences.get({ key: KEYS.SESION_TOKEN })
  const { value: tsStr } = await Preferences.get({ key: KEYS.SESION_TS })
  if (!token || !tsStr) return false
  const ts = parseInt(tsStr, 10)
  return (Date.now() - ts) < TIMEOUT_SESION_MS
}

export async function refrescarSesion(): Promise<void> {
  await Preferences.set({ key: KEYS.SESION_TS, value: Date.now().toString() })
}

// ── PIN / Registro ────────────────────────────────

export async function guardarPin(hash: string, sal: string): Promise<void> {
  await Preferences.set({ key: KEYS.PIN_HASH, value: hash })
  await Preferences.set({ key: KEYS.PIN_SAL, value: sal })
}

export async function obtenerPinHash(): Promise<string | null> {
  const { value } = await Preferences.get({ key: KEYS.PIN_HASH })
  return value
}

export async function obtenerPinSal(): Promise<string | null> {
  const { value } = await Preferences.get({ key: KEYS.PIN_SAL })
  return value
}

export async function esPrimeraVez(): Promise<boolean> {
  const { value } = await Preferences.get({ key: KEYS.INSTALADO })
  return !value
}

export async function marcarInstalado(): Promise<void> {
  await Preferences.set({ key: KEYS.INSTALADO, value: 'true' })
}

// ── Negocio (para compatibilidad con tipos existentes) ──

export function perfilANegocioInfo(perfil: PerfilEmpresa): NegocioInfo {
  return {
    id: perfil.id,
    nombre: perfil.nombre,
    nit: `${perfil.nit}-${perfil.dv}`,
  }
}
