// =====================================================
// COLINA STUDIO — Importador Seguro de XML DIAN (Fase E)
// Utiliza DOMParser nativo (inmune a XXE y bombas externas)
// =====================================================
import React, { useState } from 'react'
import { ArrowLeft, Upload, CheckCircle2, AlertTriangle, FileCode } from 'lucide-react'
import type { FacturaDetalle } from '../types'
import { agregarFactura } from '../services/localStorageService'

interface ImportarXmlModalProps {
  pin: string
  sal: string
  negocioNombre: string
  negocioNit: string
  onFacturaImportada: () => void
  onVolver: () => void
}

export const ImportarXmlModal: React.FC<ImportarXmlModalProps> = ({
  pin,
  sal,
  negocioNombre,
  negocioNit,
  onFacturaImportada,
  onVolver
}) => {
  const [cargando, setCargando] = useState(false)
  const [error, setError] = useState('')
  const [facturaPrevia, setFacturaPrevia] = useState<FacturaDetalle | null>(null)
  const [archivoNombre, setArchivoNombre] = useState('')

  const procesarTextoXML = (textoXml: string, nombre: string) => {
    setError('')
    try {
      // Protección: limitar tamaño de texto
      if (textoXml.length > 5 * 1024 * 1024) {
        throw new Error('El archivo excede el tamaño máximo permitido (5 MB).')
      }

      // DOMParser nativo no evalúa entidades externas ni DTDs
      const parser = new DOMParser()
      const doc = parser.parseFromString(textoXml, 'application/xml')

      const parseError = doc.querySelector('parsererror')
      if (parseError) {
        throw new Error('El archivo no contiene un XML válido o está dañado.')
      }

      // Helper para extraer texto de etiquetas con o sin namespace
      const getTagText = (tag: string): string => {
        const el = doc.getElementsByTagName(tag)[0] || doc.getElementsByTagNameNS('*', tag)[0]
        return el?.textContent?.trim() || ''
      }

      const numero = getTagText('ID') || `FE-IMP-${Date.now().toString().slice(-4)}`
      const fecha = getTagText('IssueDate') || new Date().toISOString().slice(0, 10)
      const hora = getTagText('IssueTime') || '12:00:00-05:00'
      const cufe = getTagText('UUID')

      // Emisor y Adquirente
      let emisor = ''
      let emisorDoc = ''
      let cliente = ''
      let clienteDoc = ''

      const supplier = doc.getElementsByTagName('AccountingSupplierParty')[0] || doc.getElementsByTagNameNS('*', 'AccountingSupplierParty')[0]
      if (supplier) {
        emisor = supplier.getElementsByTagName('Name')[0]?.textContent?.trim() ||
                 supplier.getElementsByTagName('RegistrationName')[0]?.textContent?.trim() || negocioNombre
        emisorDoc = supplier.getElementsByTagName('CompanyID')[0]?.textContent?.trim() || negocioNit
      }

      const customer = doc.getElementsByTagName('AccountingCustomerParty')[0] || doc.getElementsByTagNameNS('*', 'AccountingCustomerParty')[0]
      if (customer) {
        cliente = customer.getElementsByTagName('Name')[0]?.textContent?.trim() ||
                  customer.getElementsByTagName('RegistrationName')[0]?.textContent?.trim() || 'Cliente Adquirente'
        clienteDoc = customer.getElementsByTagName('CompanyID')[0]?.textContent?.trim() || '900000000'
      }

      // Totales
      const totalPagar = parseFloat(getTagText('PayableAmount') || '0')
      const totalImpuestos = parseFloat(getTagText('TaxInclusiveAmount') || '0')
      const subtotalVal = parseFloat(getTagText('LineExtensionAmount') || '0')
      const ivaVal = totalImpuestos > subtotalVal ? totalImpuestos - subtotalVal : 0

      const factura: FacturaDetalle = {
        id: crypto.randomUUID(),
        numeroFactura: numero,
        fecha: `${fecha}T${hora.slice(0, 8)}-05:00`,
        clienteNombre: cliente || 'Cliente Adquirente',
        clienteNIT: clienteDoc || '900000000',
        emisorNombre: emisor || negocioNombre,
        emisorNIT: emisorDoc || negocioNit,
        resolucionDIAN: 'Resolución DIAN UBL 2.1 Importada',
        formaPago: 'Contado',
        items: [],
        subtotal: subtotalVal || totalPagar,
        iva: ivaVal,
        total: totalPagar || subtotalVal,
        estado: cufe ? 'aceptada' : 'enviada',
        cufe: cufe || undefined,
        tieneQR: !!cufe,
        fechaValidacionDIAN: cufe ? `${fecha}T${hora}` : undefined
      }

      setArchivoNombre(nombre)
      setFacturaPrevia(factura)
    } catch (err: any) {
      setError(err?.message || 'Error al procesar el archivo XML.')
    }
  }

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = evt => {
      const contenido = evt.target?.result as string
      procesarTextoXML(contenido, file.name)
    }
    reader.onerror = () => setError('Error al leer el archivo desde el dispositivo.')
    reader.readAsText(file)
  }

  const confirmarImportacion = async () => {
    if (!facturaPrevia) return
    setCargando(true)
    try {
      await agregarFactura(facturaPrevia, pin, sal)
      onFacturaImportada()
    } catch {
      setError('No se pudo guardar la factura importada.')
    } finally {
      setCargando(false)
    }
  }

  return (
    <div className="modal-screen-root animate-fade-in">
      <header className="modal-screen-header">
        <button className="menu-btn-icon" onClick={onVolver} aria-label="Volver">
          <ArrowLeft size={18} />
        </button>
        <h1 className="modal-header-title font-serif">Importar XML DIAN</h1>
        <div style={{ width: 36 }} />
      </header>

      {error && (
        <div className="auth-error" style={{ margin: '1rem 1.5rem 0' }}>
          <AlertTriangle size={16} /> {error}
        </div>
      )}

      {!facturaPrevia ? (
        <div className="importar-dropzone-box">
          <div className="importar-icon-large">
            <Upload size={36} />
          </div>
          <h2 className="importar-title font-serif">Selecciona el archivo XML UBL 2.1</h2>
          <p className="importar-desc">
            Carga el archivo XML de una factura electrónica validada ante la DIAN. La app extraerá automáticamente el número, totales, cliente y CUFE sin que tengas que teclear nada.
          </p>

          <label className="btn-auth-primario btn-file-picker">
            <FileCode size={18} />
            <span>Examinar archivos...</span>
            <input
              type="file"
              accept=".xml,text/xml"
              onChange={handleFileChange}
              style={{ display: 'none' }}
            />
          </label>
        </div>
      ) : (
        <div className="importar-preview-box animate-slide-down">
          <div className="preview-status-pill">
            <CheckCircle2 size={16} />
            <span>XML procesado exitosamente</span>
          </div>

          <p className="archivo-tag font-mono">{archivoNombre}</p>

          <div className="confirmacion-resumen">
            <div className="confirmacion-row">
              <span className="confirmacion-label">Número</span>
              <span className="confirmacion-valor font-mono">{facturaPrevia.numeroFactura}</span>
            </div>
            <div className="confirmacion-row">
              <span className="confirmacion-label">Fecha</span>
              <span className="confirmacion-valor">{facturaPrevia.fecha.slice(0, 10)}</span>
            </div>
            <div className="confirmacion-row">
              <span className="confirmacion-label">Cliente</span>
              <span className="confirmacion-valor">{facturaPrevia.clienteNombre}</span>
            </div>
            <div className="confirmacion-row">
              <span className="confirmacion-label">NIT Cliente</span>
              <span className="confirmacion-valor">{facturaPrevia.clienteNIT}</span>
            </div>
            <div className="confirmacion-row">
              <span className="confirmacion-label">Total</span>
              <span className="confirmacion-valor">
                ${facturaPrevia.total.toLocaleString('es-CO')}
              </span>
            </div>
            <div className="confirmacion-row">
              <span className="confirmacion-label">Estado</span>
              <span className="confirmacion-valor">
                {facturaPrevia.cufe ? 'Validada DIAN' : 'Registrada sin validar'}
              </span>
            </div>
          </div>

          <div className="auth-btn-row" style={{ marginTop: '1.5rem' }}>
            <button className="btn-auth-secundario" onClick={() => setFacturaPrevia(null)}>
              Cambiar archivo
            </button>
            <button className="btn-auth-primario" onClick={confirmarImportacion} disabled={cargando}>
              {cargando ? 'Guardando...' : '✓ Confirmar e Importar'}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}
