// =====================================================
// COLINA STUDIO — FACTURAS ELECTRÓNICAS
// Aplicación Móvil con Navegación Profesional y Botón Atrás
// =====================================================
import React, { useState, useEffect, useCallback } from 'react'
import { SplashScreen } from './pages/SplashScreen'
import { RegistroScreen } from './pages/RegistroScreen'
import { LoginScreen } from './pages/LoginScreen'
import { DashboardV2 } from './pages/DashboardV2'
import { FacturasList } from './pages/FacturasList'
import { ReceiptView } from './components/ReceiptView'
import { MenuScreen } from './pages/MenuScreen'
import { PerfilScreen } from './pages/PerfilScreen'
import { RegistrarFacturaScreen } from './pages/RegistrarFacturaScreen'
import { ImportarXmlModal } from './pages/ImportarXmlModal'
import { EscanearQrModal } from './pages/EscanearQrModal'
import { ContadorModal } from './pages/ContadorModal'
import { BottomNav, TabDestino } from './components/BottomNav'
import { DesktopSidebar } from './components/DesktopSidebar'
import { DesktopHeader } from './components/DesktopHeader'
import { ConfirmarDescarteSheet } from './components/ConfirmarDescarteSheet'
import { useNavegacion } from './hooks/useNavegacion'
import {
  obtenerEstadoAuth, salir,
  type AuthEstado
} from './services/authService'
import {
  cargarPerfil, cargarFacturas, perfilANegocioInfo,
  refrescarSesion, type PerfilEmpresa
} from './services/localStorageService'
import {
  cargarConfiguracion, guardarConfiguracion
} from './services/configService'
import { formatearMesAñoBogota } from './utils/fechasBogota'
import {
  FacturaDetalle, NegocioInfo, ResumenPeriodo, ConfiguracionCuenta, CONFIG_DEFAULT
} from './types'

export const App: React.FC = () => {
  const [faseAuth, setFaseAuth] = useState<'splash' | 'registro' | 'login' | 'autenticado'>('splash')

  const {
    pantallaActual,
    params,
    tabActivo,
    modalActivo,
    mensajeToast,
    abrir,
    volver,
    cambiarTab,
    reiniciar,
    setModalActivo,
    setFormularioModificado
  } = useNavegacion()

  // Sesión y credenciales en memoria (Zero-Knowledge)
  const [sal, setSal] = useState('')
  const [pin, setPin] = useState('')

  // Datos del negocio, facturas y configuración
  const [perfil, setPerfil] = useState<PerfilEmpresa | null>(null)
  const [negocio, setNegocio] = useState<NegocioInfo | null>(null)
  const [config, setConfig] = useState<ConfiguracionCuenta>(CONFIG_DEFAULT)
  const [facturas, setFacturas] = useState<FacturaDetalle[]>([])
  const [resumen, setResumen] = useState<ResumenPeriodo>({
    mes: '',
    totalFacturado: 0,
    cantidadEmitidas: 0,
    cantidadAceptadas: 0,
    cantidadEnRevision: 0,
    cantidadRechazadas: 0
  })

  // Factura seleccionada activa
  const facturaSeleccionada: FacturaDetalle | null =
    (params?.factura as FacturaDetalle) || null

  // Calcular métricas
  const calcularResumen = useCallback((lista: FacturaDetalle[]): ResumenPeriodo => {
    const aceptadas = lista.filter(f => f.estado === 'aceptada')
    const enRevision = lista.filter(f => f.estado === 'enviada' || f.estado === 'firmada' || f.estado === 'borrador')
    const rechazadas = lista.filter(f => f.estado === 'rechazada')
    const totalAceptadas = aceptadas.reduce((acc, f) => acc + f.total, 0)
    const mes = formatearMesAñoBogota()
    return {
      mes,
      totalFacturado: totalAceptadas,
      cantidadEmitidas: lista.length,
      cantidadAceptadas: aceptadas.length,
      cantidadEnRevision: enRevision.length,
      cantidadRechazadas: rechazadas.length
    }
  }, [])

  // Cargar datos del usuario
  const cargarDatosUsuario = useCallback(async (pinActual: string, salActual: string) => {
    try {
      const cfg = await cargarConfiguracion()
      setConfig(cfg)

      const perfilData = await cargarPerfil(pinActual, salActual)
      if (perfilData) {
        setPerfil(perfilData)
        const neg = perfilANegocioInfo(perfilData)
        setNegocio(neg)
        if (!cfg.titularNombre || cfg.titularNombre === 'Usuario Principal') {
          cfg.titularNombre = neg.nombre
        }
      }

      const facturasData = await cargarFacturas(pinActual, salActual)
      setFacturas(facturasData)
      setResumen(calcularResumen(facturasData))
    } catch (err) {
      console.error('[Colina Studio] Error cargando datos:', err)
    }
  }, [calcularResumen])

  // Manejo de Splash
  const handleSplashDone = useCallback(async () => {
    try {
      const estado = await obtenerEstadoAuth()
      if (estado === 'primera-vez') {
        setFaseAuth('registro')
        reiniciar('registro')
      } else {
        setFaseAuth('login')
        reiniciar('login')
      }
    } catch (err) {
      console.warn('[Colina Studio] Error obteniendo estado de auth:', err)
      setFaseAuth('registro')
      reiniciar('registro')
    }
  }, [reiniciar])

  // Al registrarse
  const handleRegistrado = useCallback(async (salNueva: string, pinNuevo: string) => {
    setSal(salNueva)
    setPin(pinNuevo)
    await cargarDatosUsuario(pinNuevo, salNueva)
    setFaseAuth('autenticado')
    reiniciar('inicio')
  }, [cargarDatosUsuario, reiniciar])

  // Al hacer login con PIN
  const handleAutenticado = useCallback(async (salObtenida: string, pinIngresado: string) => {
    setSal(salObtenida)
    setPin(pinIngresado)
    await cargarDatosUsuario(pinIngresado, salObtenida)
    setFaseAuth('autenticado')
    reiniciar('inicio')
  }, [cargarDatosUsuario, reiniciar])

  // Recargar facturas tras cambios
  const recargarFacturas = useCallback(async () => {
    if (!pin || !sal) return
    const facturasActualizadas = await cargarFacturas(pin, sal)
    setFacturas(facturasActualizadas)
    setResumen(calcularResumen(facturasActualizadas))
  }, [pin, sal, calcularResumen])

  const handleFacturaCreada = useCallback(async () => {
    await recargarFacturas()
    volver()
  }, [recargarFacturas, volver])

  const handleCerrarSesion = useCallback(async () => {
    await salir()
    setSal('')
    setPin('')
    setFaseAuth('login')
    reiniciar('login')
  }, [reiniciar])

  const handleToggleTextura = useCallback(async () => {
    const nuevaCfg = { ...config, texturaPapel: !config.texturaPapel }
    setConfig(nuevaCfg)
    await guardarConfiguracion(nuevaCfg)
  }, [config])

  const handleInteraccion = useCallback(() => {
    if (faseAuth === 'autenticado') {
      refrescarSesion()
    }
  }, [faseAuth])

  // ── RENDER FASES PRE-AUTH ──────────────────────────
  if (faseAuth === 'splash') {
    return <SplashScreen onDone={handleSplashDone} />
  }

  if (faseAuth === 'registro') {
    return (
      <>
        <RegistroScreen onRegistrado={handleRegistrado} />
        {mensajeToast && <div className="app-toast-floating">{mensajeToast}</div>}
      </>
    )
  }

  if (faseAuth === 'login') {
    return (
      <>
        <LoginScreen onAutenticado={handleAutenticado} />
        {mensajeToast && <div className="app-toast-floating">{mensajeToast}</div>}
      </>
    )
  }

  // ── RENDER SUBPANTALLAS / PILA DE NAVEGACIÓN ─────────
  const negocioActivo: NegocioInfo = negocio || {
    id: 'sc-default',
    nombre: 'Soluciones Colina',
    nit: '900.123.456',
    ambiente: 'habilitacion'
  }

  // ¿Mostrar la barra de navegación inferior?
  // Solo se muestra en los 4 tabs principales si no hay subpantalla encima
  const esTabPrincipal = ['inicio', 'facturas', 'reportes', 'menu'].includes(pantallaActual)

  return (
    <div onClick={handleInteraccion} className="app-root-v2">
      {/* ── BARRA LATERAL DE ESCRITORIO (Visible >= 1024px) ── */}
      <DesktopSidebar
        tabActivo={tabActivo as TabDestino}
        pantallaActual={pantallaActual}
        negocio={negocioActivo}
        config={config}
        onCambiarTab={t => cambiarTab(t)}
        onNuevaFactura={() => abrir('nueva-factura')}
        onImportarXml={() => abrir('importar-xml')}
        onEscanearQr={() => abrir('escanear-qr')}
        onContador={() => abrir('contador')}
        onAbrirPerfil={() => abrir('perfil')}
        onCerrarSesion={handleCerrarSesion}
      />

      {/* ── CONTENEDOR PRINCIPAL DE CONTENIDO ── */}
      <div className="desktop-main-wrapper">
        <DesktopHeader
          pantallaActual={pantallaActual}
          negocio={negocioActivo}
          config={config}
          onNuevaFactura={() => abrir('nueva-factura')}
          onAbrirMenu={() => cambiarTab('menu')}
        />

        <main className="desktop-content-area">
          {/* 1. DETALLE DE FACTURA / RECIBO */}
          {pantallaActual === 'detalle-factura' && facturaSeleccionada && (
            <ReceiptView
              factura={facturaSeleccionada}
              texturaPapel={config.texturaPapel}
              onVolver={volver}
            />
          )}

          {/* 2. REGISTRAR NUEVA FACTURA */}
          {pantallaActual === 'nueva-factura' && negocio && (
            <RegistrarFacturaScreen
              pin={pin}
              sal={sal}
              negocioNombre={negocio.nombre}
              negocioNit={negocio.nit}
              onFacturaGuardada={handleFacturaCreada}
              onVolver={volver}
            />
          )}

          {/* 3. IMPORTAR XML */}
          {pantallaActual === 'importar-xml' && negocio && (
            <ImportarXmlModal
              pin={pin}
              sal={sal}
              negocioNombre={negocio.nombre}
              negocioNit={negocio.nit}
              onFacturaImportada={handleFacturaCreada}
              onVolver={volver}
            />
          )}

          {/* 4. ESCANEAR QR */}
          {pantallaActual === 'escanear-qr' && negocio && (
            <EscanearQrModal
              pin={pin}
              sal={sal}
              negocioNombre={negocio.nombre}
              negocioNit={negocio.nit}
              onFacturaRegistrada={handleFacturaCreada}
              onVolver={volver}
            />
          )}

          {/* 5. PAQUETE CONTADOR */}
          {pantallaActual === 'contador' && negocio && (
            <ContadorModal
              negocio={negocio}
              facturas={facturas}
              onVolver={volver}
            />
          )}

          {/* 6. PERFIL DE NEGOCIO */}
          {pantallaActual === 'perfil' && perfil && (
            <PerfilScreen
              perfil={perfil}
              onCerrarSesion={handleCerrarSesion}
              onVolver={volver}
            />
          )}

          {/* ── TABS PRINCIPALES ────────────────────────── */}
          {pantallaActual === 'inicio' && (
            <DashboardV2
              negocio={negocioActivo}
              resumen={resumen}
              config={config}
              facturas={facturas}
              onSeleccionarFactura={f => abrir('detalle-factura', { factura: f })}
              onVerTodas={() => cambiarTab('facturas')}
              onNuevaFactura={() => abrir('nueva-factura')}
              onImportarXml={() => abrir('importar-xml')}
              onEscanearQr={() => abrir('escanear-qr')}
              onContador={() => abrir('contador')}
              onAbrirMenu={() => cambiarTab('menu')}
            />
          )}

          {pantallaActual === 'facturas' && (
            <FacturasList
              negocio={negocioActivo}
              resumen={resumen}
              facturas={facturas}
              onSeleccionarFactura={f => abrir('detalle-factura', { factura: f })}
              onRegistrarFactura={() => abrir('nueva-factura')}
              onVerPerfil={() => abrir('perfil')}
            />
          )}

          {pantallaActual === 'reportes' && (
            <ContadorModal
              negocio={negocioActivo}
              facturas={facturas}
              onVolver={() => cambiarTab('inicio')}
            />
          )}

          {pantallaActual === 'menu' && (
            <MenuScreen
              negocio={negocioActivo}
              config={config}
              onVolver={() => cambiarTab('inicio')}
              onNavegar={destino => {
                if (destino === 'nueva-factura') abrir('nueva-factura')
                else if (destino === 'mis-facturas') cambiarTab('facturas')
                else if (destino === 'importar-xml') abrir('importar-xml')
                else if (destino === 'escanear-qr') abrir('escanear-qr')
                else if (destino === 'contador') abrir('contador')
                else if (destino === 'reportes') cambiarTab('reportes')
                else if (destino === 'perfil') abrir('perfil')
                else if (destino === 'resoluciones') abrir('contador')
                else if (destino === 'clientes') abrir('contador')
                else if (destino === 'productos') abrir('contador')
                else if (destino === 'certificado') abrir('perfil')
                else if (destino === 'ambiente-dian') abrir('perfil')
                else if (destino === 'contador-config') abrir('contador')
                else if (destino === 'seguridad') abrir('perfil')
              }}
              onEditarPerfil={() => abrir('perfil')}
              onToggleTextura={handleToggleTextura}
              onCerrarSesion={handleCerrarSesion}
            />
          )}
        </main>
      </div>

      {/* BARRA DE NAVEGACIÓN INFERIOR (Solo visible en los 4 tabs principales en móvil) */}
      {esTabPrincipal && (
        <BottomNav
          tabActivo={tabActivo as TabDestino}
          onCambiarTab={t => cambiarTab(t)}
          onNuevaFactura={() => abrir('nueva-factura')}
        />
      )}

      {/* HOJA INFERIOR: CONFIRMACIÓN DE DESCARTE DE CAMBIOS */}
      {modalActivo === 'confirmar-descarte' && (
        <ConfirmarDescarteSheet
          onSeguirEditando={() => setModalActivo(null)}
          onDescartar={() => {
            setFormularioModificado(false)
            setModalActivo(null)
            volver()
          }}
        />
      )}

      {/* TOAST FLOTANTE "PULSA OTRA VEZ PARA SALIR" */}
      {mensajeToast && <div className="app-toast-floating">{mensajeToast}</div>}
    </div>
  )
}

export default App
