// =====================================================
// COLINA STUDIO — Logo Oficial con Partículas Doradas
// Animación de partículas flotantes y aura de lujo
// =====================================================
import React, { useEffect, useRef } from 'react'
import { assetUrl } from '../utils/assets'

interface GoldenParticlesLogoProps {
  size?: number            // Tamaño del logo en px (ej. 120)
  mostrarAura?: boolean    // Halo dorado radial detrás del logo
  className?: string
  alt?: string
}

interface Particula {
  x: number
  y: number
  vx: number
  vy: number
  radio: number
  opacidad: number
  opacidadBase: number
  fase: number
  velocidadFase: number
  color: string
}

const COLORES_DORADOS = [
  '#fff3b0', // Oro brillante suave
  '#f5d77f', // Oro medio
  '#e8c872', // Oro institucional Colina
  '#c9a84c', // Oro oscuro
  '#ffffff'  // Destello blanco
]

export const GoldenParticlesLogo: React.FC<GoldenParticlesLogoProps> = ({
  size = 120,
  mostrarAura = true,
  className = '',
  alt = 'Logo Oficial Colina Studio'
}) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const animFrameId = useRef<number | null>(null)

  // El área del canvas es un poco más grande que el logo para que las partículas vuelen alrededor
  const canvasSize = Math.round(size * 1.8)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    // Soporte para pantallas Retina / High-DPI
    const dpr = window.devicePixelRatio || 1
    canvas.width = canvasSize * dpr
    canvas.height = canvasSize * dpr
    ctx.scale(dpr, dpr)

    const centroX = canvasSize / 2
    const centroY = canvasSize / 2
    const radioEmision = size * 0.45

    // Crear partículas
    const numParticulas = 28
    const particulas: Particula[] = []

    for (let i = 0; i < numParticulas; i++) {
      const angulo = Math.random() * Math.PI * 2
      const dist = Math.random() * radioEmision
      particulas.push({
        x: centroX + Math.cos(angulo) * dist,
        y: centroY + Math.sin(angulo) * dist,
        vx: (Math.random() - 0.5) * 0.35,
        vy: -0.35 - Math.random() * 0.55, // Flotan hacia arriba suavemente
        radio: 1.0 + Math.random() * 2.2,
        opacidad: Math.random() * 0.8,
        opacidadBase: 0.25 + Math.random() * 0.55,
        fase: Math.random() * Math.PI * 2,
        velocidadFase: 0.025 + Math.random() * 0.04,
        color: COLORES_DORADOS[Math.floor(Math.random() * COLORES_DORADOS.length)]
      })
    }

    let tiempo = 0

    const render = () => {
      tiempo += 1
      ctx.clearRect(0, 0, canvasSize, canvasSize)

      for (let i = 0; i < particulas.length; i++) {
        const p = particulas[i]

        // Movimiento hacia arriba con ligero bamboleo sinusoidal
        p.x += p.vx + Math.sin(tiempo * 0.03 + p.fase) * 0.25
        p.y += p.vy
        p.fase += p.velocidadFase
        p.opacidad = p.opacidadBase + Math.sin(p.fase) * 0.3

        // Si sube demasiado o sale de los márgenes, reiniciar desde abajo
        if (p.y < centroY - radioEmision * 1.4 || p.x < 0 || p.x > canvasSize) {
          const nuevoAngulo = Math.PI * 0.2 + Math.random() * Math.PI * 0.6 // Abajo
          p.x = centroX + (Math.random() - 0.5) * radioEmision * 1.3
          p.y = centroY + radioEmision * 0.8 + Math.random() * 15
          p.vy = -0.35 - Math.random() * 0.55
        }

        const alpha = Math.max(0, Math.min(1, p.opacidad))

        // Dibujar brillo exterior
        ctx.save()
        ctx.shadowBlur = p.radio * 3.5
        ctx.shadowColor = p.color
        ctx.fillStyle = p.color
        ctx.globalAlpha = alpha

        ctx.beginPath()
        ctx.arc(p.x, p.y, p.radio, 0, Math.PI * 2)
        ctx.fill()
        ctx.restore()
      }

      animFrameId.current = requestAnimationFrame(render)
    }

    render()

    return () => {
      if (animFrameId.current) {
        cancelAnimationFrame(animFrameId.current)
      }
    }
  }, [canvasSize, size])

  return (
    <div
      className={`golden-logo-container ${className}`}
      style={{
        position: 'relative',
        width: `${size}px`,
        height: `${size}px`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        margin: '0 auto'
      }}
    >
      {/* Halo de luz dorada radial detrás del logo */}
      {mostrarAura && (
        <div
          className="golden-logo-aura"
          style={{
            position: 'absolute',
            width: `${Math.round(size * 1.4)}px`,
            height: `${Math.round(size * 1.4)}px`,
            borderRadius: '50%',
            background: 'radial-gradient(circle, rgba(232, 200, 114, 0.28) 0%, rgba(201, 168, 76, 0.12) 40%, rgba(31, 58, 43, 0) 70%)',
            pointerEvents: 'none',
            zIndex: 1,
            animation: 'auraPulse 4s ease-in-out infinite'
          }}
        />
      )}

      {/* Canvas de partículas doradas flotantes */}
      <canvas
        ref={canvasRef}
        style={{
          position: 'absolute',
          width: `${canvasSize}px`,
          height: `${canvasSize}px`,
          pointerEvents: 'none',
          zIndex: 2
        }}
      />

      {/* Imagen del Logo Oficial Transparente */}
      <img
        src={assetUrl('logo.png')}
        alt={alt}
        className="golden-logo-img"
        style={{
          width: `${size}px`,
          height: `${size}px`,
          objectFit: 'contain',
          position: 'relative',
          zIndex: 3,
          filter: 'drop-shadow(0 4px 14px rgba(31, 58, 43, 0.18))',
          userSelect: 'none',
          pointerEvents: 'none'
        }}
      />
    </div>
  )
}
export default GoldenParticlesLogo
