// =====================================================
// COLINA STUDIO — Hero Card Verde Bosque con Gráfica
// Fiel a la Pantalla 6 de referencia
// =====================================================
import React from 'react'
import type { ResumenPeriodo, AmbienteDIAN } from '../types'

interface HeroCardProps {
  resumen: ResumenPeriodo
  ambiente?: AmbienteDIAN
}

export const HeroCard: React.FC<HeroCardProps> = ({
  resumen,
  ambiente = 'habilitacion'
}) => {
  const formatCOP = (val: number) =>
    val.toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 })

  // 6 meses de histórico (JUN a NOV)
  const mesesHistorico = [
    { mes: 'JUN', altura: 25, activo: false },
    { mes: 'JUL', altura: 45, activo: false },
    { mes: 'AGO', altura: 35, activo: false },
    { mes: 'SEP', altura: 60, activo: false },
    { mes: 'OCT', altura: 40, activo: false },
    { mes: 'NOV', altura: 85, activo: true }
  ]

  return (
    <div className="hero-card-forest">
      {/* Encabezado superior del Hero */}
      <div className="hero-card-head">
        <span className="hero-mes-label">
          FACTURADO EN {resumen.mes.split(' ')[0] || 'NOVIEMBRE'}
        </span>
        <span className="hero-ambiente-badge">
          {ambiente === 'habilitacion' ? 'HABILITACIÓN' : 'PRODUCCIÓN'}
        </span>
      </div>

      {/* Cifra grande protagonista */}
      <div className="hero-monto-principal font-serif">
        {formatCOP(resumen.totalFacturado)}
      </div>

      {/* Gráfica de 6 barras mensuales */}
      <div className="hero-bars-container" aria-label="Histórico de facturación últimos 6 meses">
        {mesesHistorico.map((m, idx) => (
          <div key={idx} className="hero-bar-column">
            <div className="hero-bar-track">
              <div
                className={`hero-bar-fill ${m.activo ? 'activo' : ''}`}
                style={{ height: `${m.altura}%` }}
              />
            </div>
            <span className={`hero-bar-label ${m.activo ? 'activo' : ''}`}>
              {m.mes}
            </span>
          </div>
        ))}
      </div>

      {/* Desglose de estados en puntos de colores */}
      <div className="hero-footer-stats">
        <div className="hero-dots-row">
          <span className="hero-stat-item">
            <span className="dot dot-verde" /> {resumen.cantidadAceptadas || 3} aceptadas
          </span>
          <span className="hero-stat-item">
            <span className="dot dot-amarillo" /> {resumen.cantidadEnRevision || 1} en revisión
          </span>
          <span className="hero-stat-item">
            <span className="dot dot-rojo" /> {resumen.cantidadRechazadas || 1} rechazada
          </span>
        </div>
        <span className="hero-modo-tag">Modo Local</span>
      </div>
    </div>
  )
}
