// =====================================================
import React from 'react'
import { ArrowLeft, Archive, Download, FileSpreadsheet, Check } from 'lucide-react'
import type { FacturaDetalle, NegocioInfo } from '../types'

interface ContadorModalProps {
  negocio: NegocioInfo
  facturas: FacturaDetalle[]
  onVolver: () => void
}

export const ContadorModal: React.FC<ContadorModalProps> = ({
  negocio,
  facturas,
  onVolver
}) => {
  const formatCOP = (val: number) =>
    val.toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 })

  // Generar CSV para contabilidad
  const exportarCSV = () => {
    const cabecera = [
      'Numero Factura',
      'Fecha',
      'NIT Emisor',
      'Emisor',
      'NIT Adquirente',
      'Cliente',
      'Subtotal COP',
      'IVA COP',
      'Total Factura COP',
      'Forma de Pago',
      'CUFE',
      'Estado DIAN'
    ].join(';')

    const filas = facturas.map(f => [
      `"${f.numeroFactura}"`,
      `"${f.fecha.slice(0, 10)}"`,
      `"${f.emisorNIT}"`,
      `"${f.emisorNombre}"`,
      `"${f.clienteNIT}"`,
      `"${f.clienteNombre}"`,
      f.subtotal,
      f.iva,
      f.total,
      `"${f.formaPago}"`,
      `"${f.cufe || ''}"`,
      `"${f.estado}"`
    ].join(';'))

    const contenido = [cabecera, ...filas].join('\r\n')
    const blob = new Blob(['\uFEFF' + contenido], { type: 'text/csv;charset=utf-8;' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = `Libro_Ventas_${negocio.nombre.replace(/\s+/g, '_')}_Noviembre_2026.csv`
    link.click()
  }

  const totalPeriodo = facturas.reduce((sum, f) => sum + f.total, 0)
  const totalIva = facturas.reduce((sum, f) => sum + f.iva, 0)

  return (
    <div className="modal-screen-root animate-fade-in">
      <header className="modal-screen-header">
        <button className="menu-btn-icon" onClick={onVolver} aria-label="Volver">
          <ArrowLeft size={18} />
        </button>
        <h1 className="modal-header-title font-serif">Paquete del Contador</h1>
        <div style={{ width: 36 }} />
      </header>

      <div className="contador-box">
        <div className="contador-icon-large">
          <Archive size={36} />
        </div>

        <h2 className="contador-title font-serif">Libro Mensual de Facturación</h2>
        <p className="contador-desc">
          Exporta el libro de ventas en formato CSV/Excel con todas las facturas del periodo, CUFE, IVA discriminado y totales cuadrados al peso para tu contador.
        </p>

        <div className="contador-resumen-card">
          <div className="contador-resumen-row">
            <span>Facturas en el periodo:</span>
            <strong>{facturas.length}</strong>
          </div>
          <div className="contador-resumen-row">
            <span>Total IVA discriminado:</span>
            <strong>{formatCOP(totalIva)}</strong>
          </div>
          <div className="contador-resumen-row total-highlight">
            <span>Total facturado:</span>
            <strong>{formatCOP(totalPeriodo)}</strong>
          </div>
        </div>

        <button className="btn-auth-primario" onClick={exportarCSV} style={{ marginTop: '1.5rem' }}>
          <FileSpreadsheet size={18} />
          <span>Descargar Libro en Excel / CSV</span>
        </button>

        <p className="contador-hint">
          Desarrollado conforme a la estructura de conciliación contable DIAN por Colina Studio.
        </p>
      </div>
    </div>
  )
}
