// =====================================================
// COLINA STUDIO / FACTURAS ELECTRONICAS
// Header Superior de Escritorio (Desktop Header >= 1024px)
// =====================================================
import React from 'react'
import { Plus } from 'lucide-react'
import type { NegocioInfo, ConfiguracionCuenta } from '../types'
import { hoyBogota } from '../utils/fechasBogota'

interface DesktopHeaderProps {
  pantallaActual: string
  negocio: NegocioInfo
  config: ConfiguracionCuenta
  onNuevaFactura: () => void
  onAbrirMenu: () => void
}

export const DesktopHeader: React.FC<DesktopHeaderProps> = ({
  pantallaActual,
  negocio,
  config,
  onNuevaFactura
}) => {
  const titular = config.titularNombre || negocio.nombre || 'Administrador'

  const obtenerTituloSeccion = () => {
    switch (pantallaActual) {
      case 'inicio':
        return `Bienvenido, ${titular}`
      case 'facturas':
        return 'Mis Facturas Electrónicas'
      case 'detalle-factura':
        return 'Detalle de Factura DIAN'
      case 'nueva-factura':
        return 'Emisión de Nueva Factura'
      case 'importar-xml':
        return 'Importar Archivo XML DIAN'
      case 'escanear-qr':
        return 'Escanear Código QR DIAN'
      case 'reportes':
      case 'contador':
        return 'Paquete del Contador & Reportes'
      case 'menu':
        return 'Menú de Configuración'
      case 'perfil':
        return 'Perfil del Negocio'
      default:
        return 'Soluciones Colina'
    }
  }

  return (
    <header className="desktop-header">
      <div className="desktop-header-left">
        <h2 className="desktop-header-section-title font-serif">
          {obtenerTituloSeccion()}
        </h2>
        <span className="desktop-header-location">
          Colombia (UTC-05:00) · {hoyBogota()}
        </span>
      </div>

      <div className="desktop-header-right">
        <span className="desktop-clock-tag">
          {config.ambienteDIAN === 'produccion' ? 'DIAN Producción' : 'DIAN Habilitación'}
        </span>

        {pantallaActual !== 'nueva-factura' && (
          <button
            type="button"
            className="desktop-sidebar-cta"
            style={{ width: 'auto', marginBottom: 0, padding: '0.5rem 1rem' }}
            onClick={onNuevaFactura}
          >
            <Plus size={16} />
            <span>Emitir Factura</span>
          </button>
        )}
      </div>
    </header>
  )
}
