import React, { useEffect } from 'react'
import { GoldenParticlesLogo } from '../components/GoldenParticlesLogo'

interface SplashScreenProps {
  onDone: () => void
}

export const SplashScreen: React.FC<SplashScreenProps> = ({ onDone }) => {
  useEffect(() => {
    const timer = setTimeout(onDone, 1800)
    return () => clearTimeout(timer)
  }, [onDone])

  return (
    <div
      className="splash-root"
      onClick={onDone}
      role="button"
      tabIndex={0}
      title="Clic para ingresar"
      style={{ cursor: 'pointer' }}
    >
      <div className="splash-contenido">
        <GoldenParticlesLogo size={135} mostrarAura={true} />
        <h1 className="splash-titulo font-serif">Soluciones Colina</h1>
        <p className="splash-sub">Gestión de Facturación Electrónica</p>
        <div className="splash-loader">
          <div className="splash-loader-bar" />
        </div>
      </div>
      <span className="splash-footer">Por Colina Studio · Colombia</span>
    </div>
  )
}
export default SplashScreen
