// COLINA STUDIO — Barra de Navegación Inferior (5 destinos)
// =====================================================
import React from 'react'
import { Home, FileText, Plus, BarChart3, Menu } from 'lucide-react'

export type TabDestino = 'inicio' | 'facturas' | 'reportes' | 'menu'

interface BottomNavProps {
  tabActivo: TabDestino
  onCambiarTab: (tab: TabDestino) => void
  onNuevaFactura: () => void
}

export const BottomNav: React.FC<BottomNavProps> = ({
  tabActivo,
  onCambiarTab,
  onNuevaFactura
}) => {
  return (
    <nav className="bottom-nav-bar" aria-label="Navegación principal">
      <button
        className={`bottom-nav-item ${tabActivo === 'inicio' ? 'activo' : ''}`}
        onClick={() => onCambiarTab('inicio')}
        aria-label="Ir a Inicio"
      >
        <Home size={20} />
        <span>Inicio</span>
      </button>

      <button
        className={`bottom-nav-item ${tabActivo === 'facturas' ? 'activo' : ''}`}
        onClick={() => onCambiarTab('facturas')}
        aria-label="Ir a Facturas"
      >
        <FileText size={20} />
        <span>Facturas</span>
      </button>

      {/* Botón central elevado */}
      <div className="bottom-nav-center-wrapper">
        <button
          className="bottom-nav-fab"
          onClick={onNuevaFactura}
          aria-label="Registrar nueva factura"
        >
          <Plus size={24} />
        </button>
      </div>

      <button
        className={`bottom-nav-item ${tabActivo === 'reportes' ? 'activo' : ''}`}
        onClick={() => onCambiarTab('reportes')}
        aria-label="Ir a Reportes"
      >
        <BarChart3 size={20} />
        <span>Reportes</span>
      </button>

      <button
        className={`bottom-nav-item ${tabActivo === 'menu' ? 'activo' : ''}`}
        onClick={() => onCambiarTab('menu')}
        aria-label="Abrir Menú"
      >
        <Menu size={20} />
        <span>Menú</span>
      </button>
    </nav>
  )
}
