import React from 'react'
import type { FacturaDetalle } from '../types'
import { ReceiptTeeth } from './ReceiptTeeth'

interface MiniReceiptCardProps {
  factura: FacturaDetalle
  onClick: () => void
}

export const MiniReceiptCard: React.FC<MiniReceiptCardProps> = ({ factura, onClick }) => {
  const formatCOP = (val: number) =>
    val.toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 })

  const formatearFechaCorta = (isoStr: string) => {
    try {
      const d = new Date(isoStr)
      const dia = d.getDate().toString().padStart(2, '0')
      const mes = (d.getMonth() + 1).toString().padStart(2, '0')
      return `${dia}/${mes}`
    } catch {
      return ''
    }
  }

  // Mapeo honesto de badges
  const obtenerBadge = () => {
    if (factura.estado === 'aceptada') {
      return <span className="mini-badge badge-aceptada">Aceptada</span>
    }
    if (factura.estado === 'rechazada') {
      return <span className="mini-badge badge-rechazada">Rechazada</span>
    }
    return <span className="mini-badge badge-revision">En revisión</span>
  }

  return (
    <button
      type="button"
      className="mini-receipt-wrapper"
      onClick={onClick}
      aria-label={`Factura ${factura.numeroFactura}, ${factura.clienteNombre}, total ${formatCOP(factura.total)}`}
    >
      <div className="mini-receipt-card">
        <div className="mini-receipt-top">
          <span className="mini-receipt-num font-serif">{factura.numeroFactura}</span>
          <span className="mini-receipt-total font-sans">{formatCOP(factura.total)}</span>
        </div>
        <div className="mini-receipt-bottom">
          <span className="mini-receipt-cliente">
            {factura.clienteNombre} · {formatearFechaCorta(factura.fecha)}
          </span>
          {obtenerBadge()}
        </div>
      </div>
      <ReceiptTeeth color="#fffdf8" fondo="transparent" />
    </button>
  )
}
