/** Estado de una factura ante la DIAN */
export type EstadoFactura =
  | 'borrador'
  | 'firmada'
  | 'enviada'     // registrada localmente, sin validar
  | 'aceptada'    // respuesta oficial DIAN con CUFE
  | 'rechazada'   // respuesta DIAN con error
  | 'anulada'     // nota crédito total

/** Ambiente DIAN */
export type AmbienteDIAN = 'habilitacion' | 'produccion'

/** Ítem o línea de detalle de la factura */
export interface ItemFacturaCliente {
  id?: string
  descripcion: string
  cantidad: number
  precioUnitario: number
  total: number
  iva?: number
  porcentajeIVA?: number // 19, 5, 0
}

/** Resumen de factura para listas y mini-recibos */
export interface FacturaResumen {
  id: string
  numeroFactura: string    // Ej. FE-0005
  fecha: string            // ISO 8601 America/Bogota
  clienteNombre: string
  clienteNIT: string
  total: number
  estado: EstadoFactura
  cufe?: string
  tieneQR?: boolean
  ambiente?: AmbienteDIAN
}

/** Factura completa para vista recibo y PDF */
export interface FacturaDetalle extends FacturaResumen {
  emisorNombre: string
  emisorNIT: string
  emisorRegimen?: string
  emisorDireccion?: string
  emisorCiudad?: string
  resolucionDIAN: string
  formaPago: string        // 'Contado · Transferencia' | 'Crédito' | etc.
  items: ItemFacturaCliente[]
  subtotal: number
  iva: number
  urlPDF?: string
  urlXML?: string
  qrUrl?: string
  fechaValidacionDIAN?: string
  motivo?: string          // mensaje de error si fue rechazada
  softwareFabricante?: string // 'Colina Studio'
}

/** Información del negocio emisor */
export interface NegocioInfo {
  id: string
  nombre: string
  nit: string
  dv?: string
  regimen?: string
  direccion?: string
  ciudad?: string
  logoUrl?: string
  correo?: string
  telefono?: string
  ambiente?: AmbienteDIAN
}

/** Resumen de métricas para el Hero Card */
export interface ResumenPeriodo {
  mes: string               // "NOVIEMBRE 2026"
  totalFacturado: number    // total aceptadas
  cantidadEmitidas: number
  cantidadAceptadas: number
  cantidadEnRevision: number
  cantidadRechazadas: number
  historicoMeses?: Array<{ mes: string; total: number; activo?: boolean }>
}

/** Resolución de facturación DIAN */
export interface ResolucionDIAN {
  id: string
  numeroResolucion: string // Ej. 18764000001
  prefijo: string          // Ej. FE
  rangoDesde: number       // 1
  rangoHasta: number       // 10000
  ultimoConsecutivo: number // 5
  fechaInicio: string
  fechaFin: string
  vigenciaMeses: number
  claveTecnica?: string
}

/** Cliente frecuente */
export interface ClienteFrecuente {
  id: string
  nombre: string
  nit: string
  dv: string
  correo: string
  telefono?: string
  ciudad?: string
}

/** Producto o servicio del catálogo */
export interface ProductoServicio {
  id: string
  codigo: string
  nombre: string
  precioUnitario: number
  tarifaIVA: number        // 19, 5, 0
}

/** Configuración de la cuenta y preferencias */
export interface ConfiguracionCuenta {
  texturaPapel: boolean    // Interruptor de textura arrugada en pantalla
  ambienteDIAN: AmbienteDIAN
  formatoFactura: 'recibo' | 'carta' | 'ambos'
  correoContador: string
  envioAutomaticoContador: boolean
  notificacionesRango: boolean
  titularNombre?: string
  planNombre?: string
}

export const CONFIG_DEFAULT: ConfiguracionCuenta = {
  texturaPapel: true,
  ambienteDIAN: 'habilitacion',
  formatoFactura: 'ambos',
  correoContador: '',
  envioAutomaticoContador: false,
  notificacionesRango: true,
  titularNombre: 'Usuario Principal',
  planNombre: 'PLAN PRO'
}
