// =====================================================
// SOLUCIONES COLINA — Pantalla de Login con PIN
// =====================================================
import React, { useState, useRef, useEffect } from 'react'
import { verificarPin } from '../services/authService'
import { GoldenParticlesLogo } from '../components/GoldenParticlesLogo'

interface LoginScreenProps {
  onAutenticado: (sal: string, pin: string) => void
}

export const LoginScreen: React.FC<LoginScreenProps> = ({ onAutenticado }) => {
  const [pin, setPin] = useState('')
  const [error, setError] = useState('')
  const [cargando, setCargando] = useState(false)
  const [intentos, setIntentos] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    // Auto-focus al abrir
    setTimeout(() => inputRef.current?.focus(), 300)
  }, [])

  const handlePinChange = async (valor: string) => {
    const limpio = valor.replace(/\D/g, '').slice(0, 6)
    setPin(limpio)
    setError('')

    // Auto-verificar cuando llega a 6 dígitos
    if (limpio.length === 6) {
      await verificar(limpio)
    }
  }

  const verificar = async (pinIngresado: string) => {
    setCargando(true)
    try {
      const sal = await verificarPin(pinIngresado)
      if (sal) {
        onAutenticado(sal, pinIngresado)
      } else {
        const nuevosIntentos = intentos + 1
        setIntentos(nuevosIntentos)
        setPin('')
        setError(
          nuevosIntentos >= 3
            ? `PIN incorrecto. ${5 - nuevosIntentos} intentos restantes.`
            : 'PIN incorrecto. Intenta de nuevo.'
        )
        inputRef.current?.focus()
      }
    } catch {
      setError('Error al verificar PIN. Intenta de nuevo.')
      setPin('')
    } finally {
      setCargando(false)
    }
  }

  // Bloqueo temporal tras 5 intentos fallidos
  const bloqueado = intentos >= 5

  return (
    <div className="auth-root">
      <div className="auth-card">
        <GoldenParticlesLogo size={92} mostrarAura={true} />
        <h1 className="auth-titulo font-serif">Soluciones Colina</h1>
        <p className="auth-sub">Ingresa tu PIN para continuar</p>

        {bloqueado ? (
          <div className="auth-bloqueado">
            🔒 Acceso bloqueado por múltiples intentos fallidos.
            <br />Reinicia la app e intenta de nuevo.
          </div>
        ) : (
          <div className="auth-form">
            {/* Indicador visual del PIN */}
            <div className="pin-dots-row" onClick={() => inputRef.current?.focus()}>
              {Array.from({ length: 6 }).map((_, i) => (
                <div
                  key={i}
                  className={`pin-dot ${i < pin.length ? 'lleno' : ''} ${error && i < pin.length ? 'error' : ''}`}
                />
              ))}
            </div>

            {/* Input oculto para capturar el PIN */}
            <input
              ref={inputRef}
              className="pin-input-oculto"
              type="password"
              inputMode="numeric"
              maxLength={6}
              value={pin}
              onChange={e => handlePinChange(e.target.value)}
              disabled={cargando || bloqueado}
              autoComplete="current-password"
            />

            {error && <div className="auth-error">{error}</div>}
            {cargando && <div className="auth-cargando">Verificando...</div>}

            <p className="pin-hint">
              Toca los puntos y escribe tu PIN de 6 dígitos
            </p>
          </div>
        )}
      </div>
    </div>
  )
}
