import React from 'react'
import type { PerfilEmpresa } from '../services/localStorageService'
import { salir } from '../services/authService'

interface PerfilScreenProps {
  perfil: PerfilEmpresa
  onCerrarSesion: () => void
  onVolver: () => void
}

export const PerfilScreen: React.FC<PerfilScreenProps> = ({ perfil, onCerrarSesion, onVolver }) => {
  const handleCerrarSesion = async () => {
    if (confirm('¿Deseas cerrar sesión? Deberás ingresar tu PIN nuevamente.')) {
      await salir()
      onCerrarSesion()
    }
  }

  const formatearFecha = (iso: string) => {
    return new Date(iso).toLocaleDateString('es-CO', {
      day: '2-digit',
      month: 'long',
      year: 'numeric',
      timeZone: 'America/Bogota'
    })
  }

  return (
    <div className="perfil-root">
      <div className="perfil-header">
        <button className="btn-volver" onClick={onVolver}>
          ← Volver
        </button>
        <h2 className="perfil-titulo font-serif">Mi Empresa</h2>
      </div>

      <div className="perfil-avatar-section">
        <div className="perfil-avatar-grande">
          {perfil.nombre.charAt(0).toUpperCase()}
        </div>
        <h3 className="perfil-nombre">{perfil.nombre}</h3>
        <span className="perfil-nit">NIT {perfil.nit}-{perfil.dv}</span>
      </div>

      <div className="perfil-datos">
        <div className="perfil-dato-row">
          <span className="perfil-dato-label">Correo</span>
          <span className="perfil-dato-valor">{perfil.correo}</span>
        </div>
        {perfil.telefono && (
          <div className="perfil-dato-row">
            <span className="perfil-dato-label">Teléfono</span>
            <span className="perfil-dato-valor">{perfil.telefono}</span>
          </div>
        )}
        {perfil.ciudad && (
          <div className="perfil-dato-row">
            <span className="perfil-dato-label">Ciudad</span>
            <span className="perfil-dato-valor">{perfil.ciudad}</span>
          </div>
        )}
        <div className="perfil-dato-row">
          <span className="perfil-dato-label">Cuenta creada</span>
          <span className="perfil-dato-valor">{formatearFecha(perfil.creadoEn)}</span>
        </div>
      </div>

      <div className="perfil-aviso">
        🔒 Plataforma de Facturación Electrónica DIAN desarrollada por Colina Studio.
      </div>

      <button className="btn-cerrar-sesion" onClick={handleCerrarSesion}>
        Cerrar sesión
      </button>
    </div>
  )
}
