// COLINA STUDIO / FACTURAS ELECTRONICAS
// Módulo de Navegación Profesional con Pila e Historial
// Soporte para botón Atrás de Android (Capacitor App)
// =====================================================
import { App as CapApp } from '@capacitor/app'
import { StatusBar, Style } from '@capacitor/status-bar'

export type TabId = 'inicio' | 'facturas' | 'reportes' | 'menu'

export type PantallaId =
  | 'splash'
  | 'registro'
  | 'login'
  | 'inicio'
  | 'facturas'
  | 'reportes'
  | 'menu'
  | 'detalle-factura'
  | 'nueva-factura'
  | 'importar-xml'
  | 'escanear-qr'
  | 'contador'
  | 'perfil'
  | 'config-resoluciones'
  | 'config-clientes'
  | 'config-productos'
  | 'config-seguridad'

export interface EntradaNavegacion {
  pantalla: PantallaId
  params?: Record<string, any>
}

export interface EstadoNavegacion {
  pila: EntradaNavegacion[]
  tabActivo: TabId
  modalActivo: string | null
  formularioModificado: boolean
  mensajeToast: string | null
}

export type ListenerNavegacion = (estado: EstadoNavegacion) => void

export class ManejadorNavegacion {
  private estado: EstadoNavegacion = {
    pila: [{ pantalla: 'splash' }],
    tabActivo: 'inicio',
    modalActivo: null,
    formularioModificado: false,
    mensajeToast: null
  }

  private listeners: Set<ListenerNavegacion> = new Set()
  private ultimoTapAtrasInicio: number = 0
  private timerToast: any = null
  private capListenerRemover: (() => void) | null = null

  constructor() {
    this.iniciarListenerHardware()
  }

  public obtenerEstado(): EstadoNavegacion {
    return { ...this.estado }
  }

  public suscribir(listener: ListenerNavegacion): () => void {
    this.listeners.add(listener)
    listener(this.obtenerEstado())
    return () => this.listeners.delete(listener)
  }

  private notificar() {
    const estadoCopia = this.obtenerEstado()
    this.listeners.forEach(l => l(estadoCopia))
  }

  /**
   * Configura la barra de estado con iconos oscuros y fondo crema
   */
  public async configurarBarraEstado() {
    try {
      await StatusBar.setStyle({ style: Style.Light })
      await StatusBar.setBackgroundColor({ color: '#f5efe3' })
    } catch {
      // Entorno web, ignorar
    }
  }

  /**
   * Abre una nueva pantalla apilándola
   */
  public abrir(pantalla: PantallaId, params?: Record<string, any>) {
    // Si es un tab principal
    if (['inicio', 'facturas', 'reportes', 'menu'].includes(pantalla)) {
      this.cambiarTab(pantalla as TabId)
      return
    }

    this.estado.modalActivo = null
    this.estado.formularioModificado = false
    this.estado.pila = [...this.estado.pila, { pantalla, params }]
    this.notificar()
  }

  /**
   * Cambia el tab principal
   */
  public cambiarTab(tab: TabId) {
    this.estado.tabActivo = tab
    this.estado.modalActivo = null
    this.estado.formularioModificado = false
    this.estado.pila = [{ pantalla: tab }]
    this.notificar()
  }

  /**
   * Reemplaza la pantalla actual en el tope de la pila
   */
  public reemplazar(pantalla: PantallaId, params?: Record<string, any>) {
    const copia = [...this.estado.pila]
    if (copia.length > 0) {
      copia[copia.length - 1] = { pantalla, params }
    } else {
      copia.push({ pantalla, params })
    }
    this.estado.pila = copia
    this.estado.modalActivo = null
    this.estado.formularioModificado = false
    this.notificar()
  }

  /**
   * Reinicia la navegación a una pantalla raíz (ej. login o inicio tras registrarse)
   */
  public reiniciar(pantalla: PantallaId, params?: Record<string, any>) {
    this.estado.pila = [{ pantalla, params }]
    if (['inicio', 'facturas', 'reportes', 'menu'].includes(pantalla)) {
      this.estado.tabActivo = pantalla as TabId
    }
    this.estado.modalActivo = null
    this.estado.formularioModificado = false
    this.notificar()
  }

  /**
   * Indica si el formulario actual tiene cambios sin guardar
   */
  public setFormularioModificado(modificado: boolean) {
    if (this.estado.formularioModificado !== modificado) {
      this.estado.formularioModificado = modificado
      this.notificar()
    }
  }

  /**
   * Abre o cierra un diálogo o modal flotante
   */
  public setModalActivo(modal: string | null) {
    this.estado.modalActivo = modal
    this.notificar()
  }

  /**
   * Muestra un mensaje flotante temporal (Toast)
   */
  public mostrarToast(mensaje: string, duracionMs: number = 2000) {
    if (this.timerToast) clearTimeout(this.timerToast)
    this.estado.mensajeToast = mensaje
    this.notificar()

    this.timerToast = setTimeout(() => {
      this.estado.mensajeToast = null
      this.notificar()
    }, duracionMs)
  }

  /**
   * Manejador universal del botón Atrás con la prioridad exigida:
   * 1. Si hay un diálogo o modal abierto -> cerrarlo.
   * 2. Si el formulario tiene cambios -> abrir diálogo de confirmación de descarte.
   * 3. Si hay una pantalla encima en la pila -> volver a la anterior.
   * 4. Si estamos en un tab distinto de 'inicio' -> volver a 'inicio'.
   * 5. Si estamos en 'inicio' -> pedir 2do tap ("Pulsa otra vez para salir") para salir de la app.
   */
  public retroceder(): boolean {
    // 1. Diálogo / Modal abierto
    if (this.estado.modalActivo) {
      this.estado.modalActivo = null
      this.notificar()
      return true
    }

    // 2. Formulario con cambios sin guardar
    if (this.estado.formularioModificado) {
      this.estado.modalActivo = 'confirmar-descarte'
      this.notificar()
      return true
    }

    // Pantalla actual en la cima
    const cima = this.estado.pila[this.estado.pila.length - 1]
    const pantallaActual = cima?.pantalla

    // Pantallas pre-autenticación (Splash, Registro, Login)
    if (pantallaActual === 'splash') {
      return false
    }

    if (pantallaActual === 'registro' || pantallaActual === 'login') {
      const ahora = Date.now()
      if (ahora - this.ultimoTapAtrasInicio < 2000) {
        this.salirDeApp()
        return true
      }
      this.ultimoTapAtrasInicio = ahora
      this.mostrarToast('Pulsa otra vez para salir')
      return true
    }

    // 3. Pantalla encima en la pila
    if (this.estado.pila.length > 1) {
      this.estado.pila = this.estado.pila.slice(0, -1)
      this.notificar()
      return true
    }

    // 4. Tab diferente a inicio
    if (this.estado.tabActivo !== 'inicio') {
      this.cambiarTab('inicio')
      return true
    }

    // 5. En tab inicio -> confirmación doble para salir
    const ahora = Date.now()
    if (ahora - this.ultimoTapAtrasInicio < 2000) {
      this.salirDeApp()
      return true
    }
    this.ultimoTapAtrasInicio = ahora
    this.mostrarToast('Pulsa otra vez para salir')
    return true
  }

  public salirDeApp() {
    try {
      CapApp.exitApp()
    } catch {
      // En navegador no hace nada
    }
  }

  private iniciarListenerHardware() {
    try {
      const listenerPromise = CapApp.addListener('backButton', () => {
        this.retroceder()
      })
      listenerPromise.then(handler => {
        this.capListenerRemover = () => handler.remove()
      }).catch(() => {})
    } catch {
      // Entorno no nativo
    }
  }

  public destruir() {
    if (this.capListenerRemover) {
      this.capListenerRemover()
    }
    if (this.timerToast) {
      clearTimeout(this.timerToast)
    }
  }
}

// Instancia singleton para toda la app
export const navegador = new ManejadorNavegacion()
