// =====================================================
// SOLUCIONES COLINA — Pantalla Registrar Factura
// Formulario para ingresar datos de una nueva factura DIAN
// =====================================================
import React, { useState, useEffect } from 'react'
import type { FacturaDetalle } from '../types'
import { agregarFactura } from '../services/localStorageService'
import { hoyBogota, obtenerPartesFechaBogota } from '../utils/fechasBogota'
import { cargarResoluciones, asignarSiguienteConsecutivo } from '../services/configService'
import { navegador } from '../services/navigationService'

interface RegistrarFacturaScreenProps {
  pin: string
  sal: string
  negocioNombre: string
  negocioNit: string
  onFacturaGuardada: () => void
  onVolver: () => void
}

export const RegistrarFacturaScreen: React.FC<RegistrarFacturaScreenProps> = ({
  pin, sal, negocioNombre, negocioNit, onFacturaGuardada, onVolver
}) => {
  const [cargando, setCargando] = useState(false)
  const [error, setError] = useState('')

  // Campos principales
  const [numeroFactura, setNumeroFactura] = useState('')
  const [fecha, setFecha] = useState(hoyBogota())
  const [clienteNombre, setClienteNombre] = useState('')
  const [clienteNIT, setClienteNIT] = useState('')
  const [resolucionDIAN, setResolucionDIAN] = useState('')
  const [resolucionIdActiva, setResolucionIdActiva] = useState('')
  const [formaPago, setFormaPago] = useState('Contado')
  const [cufe, setCufe] = useState('')

  useEffect(() => {
    // Cargar resoluciones para autonumeración
    cargarResoluciones().then(resList => {
      if (resList.length > 0) {
        const res = resList[0]
        setResolucionIdActiva(res.id)
        const siguiente = res.ultimoConsecutivo + 1
        setNumeroFactura(`${res.prefijo}-${siguiente.toString().padStart(4, '0')}`)
        setResolucionDIAN(`Resolución DIAN ${res.numeroResolucion} (${res.prefijo} ${res.rangoDesde}-${res.rangoHasta})`)
      }
    })
  }, [])

  // Totales
  const [subtotal, setSubtotal] = useState('')
  const [iva, setIva] = useState('')

  const total = (parseFloat(subtotal || '0') + parseFloat(iva || '0'))

  useEffect(() => {
    return () => {
      navegador.setFormularioModificado(false)
    }
  }, [])

  const marcarModificado = () => {
    navegador.setFormularioModificado(true)
  }

  const formatCOP = (val: number) =>
    val.toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 })

  const soloNumeros = (val: string) => val.replace(/[^0-9.]/g, '')

  const validar = () => {
    if (!numeroFactura.trim()) return 'El número de factura es obligatorio'
    if (!clienteNombre.trim()) return 'El nombre del cliente es obligatorio'
    if (!clienteNIT.trim()) return 'El NIT del cliente es obligatorio'
    if (!resolucionDIAN.trim()) return 'La resolución DIAN es obligatoria'
    if (parseFloat(subtotal || '0') <= 0) return 'El subtotal debe ser mayor a 0'
    return ''
  }

  const guardar = async () => {
    const err = validar()
    if (err) { setError(err); return }
    setCargando(true)
    setError('')
    try {
      if (resolucionIdActiva) {
        try {
          await asignarSiguienteConsecutivo(resolucionIdActiva)
        } catch (e) {
          console.warn('No se pudo incrementar consecutivo:', e)
        }
      }
      const partesHora = obtenerPartesFechaBogota()
      const factura: FacturaDetalle = {
        id: crypto.randomUUID(),
        numeroFactura: numeroFactura.toUpperCase(),
        fecha: `${fecha}T${partesHora.cadenaHora}-05:00`,
        clienteNombre,
        clienteNIT,
        emisorNombre: negocioNombre,
        emisorNIT: negocioNit,
        resolucionDIAN,
        formaPago,
        items: [],
        subtotal: parseFloat(subtotal || '0'),
        iva: parseFloat(iva || '0'),
        total,
        estado: 'enviada',
        cufe: cufe.trim() || undefined,
        tieneQR: !!cufe.trim(),
      }
      await agregarFactura(factura, pin, sal)
      navegador.setFormularioModificado(false)
      onFacturaGuardada()
    } catch {
      setError('No se pudo guardar la factura. Intenta de nuevo.')
    } finally {
      setCargando(false)
    }
  }

  return (
    <div className="registrar-root">
      <div className="registrar-header">
        <button className="btn-volver" onClick={onVolver}>← Volver</button>
        <h2 className="registrar-titulo font-serif">Registrar Factura</h2>
      </div>

      {error && <div className="auth-error">{error}</div>}

      <div className="registrar-form">
        <div className="campo-grupo">
          <label className="campo-label">Número de Factura *</label>
          <input className="campo-input" type="text" placeholder="Ej. FE-0001" value={numeroFactura}
            onChange={e => setNumeroFactura(e.target.value)} />
        </div>

        <div className="campo-grupo">
          <label className="campo-label">Fecha de Emisión (Bogotá) *</label>
          <input className="campo-input" type="date" value={fecha}
            onChange={e => setFecha(e.target.value)} />
        </div>

        <div className="campo-grupo">
          <label className="campo-label">Nombre del Cliente / Adquiriente *</label>
          <input className="campo-input" type="text" placeholder="Ej. Constructora Los Pinos SAS"
            value={clienteNombre} onChange={e => { setClienteNombre(e.target.value); marcarModificado() }} />
        </div>

        <div className="campo-grupo">
          <label className="campo-label">NIT o CC del Cliente *</label>
          <input className="campo-input" type="text" inputMode="numeric"
            placeholder="Ej. 900.123.456" value={clienteNIT}
            onChange={e => { setClienteNIT(e.target.value.replace(/\D/g, '')); marcarModificado() }} />
        </div>

        <div className="campo-grupo">
          <label className="campo-label">Resolución DIAN *</label>
          <input className="campo-input" type="text" placeholder="Ej. 18760000001"
            value={resolucionDIAN} onChange={e => setResolucionDIAN(e.target.value)} />
        </div>

        <div className="campo-grupo">
          <label className="campo-label">Forma de Pago</label>
          <select className="campo-input" value={formaPago} onChange={e => setFormaPago(e.target.value)}>
            <option value="Contado">Contado</option>
            <option value="Crédito">Crédito</option>
            <option value="Transferencia">Transferencia</option>
          </select>
        </div>

        <div className="campo-row">
          <div className="campo-grupo campo-flex">
            <label className="campo-label">Subtotal (COP) *</label>
            <input className="campo-input" type="text" inputMode="numeric"
              placeholder="Ej. 1.000.000" value={subtotal}
              onChange={e => setSubtotal(soloNumeros(e.target.value))} />
          </div>
          <div className="campo-grupo campo-flex">
            <label className="campo-label">IVA (COP)</label>
            <input className="campo-input" type="text" inputMode="numeric"
              placeholder="Ej. 190.000" value={iva}
              onChange={e => setIva(soloNumeros(e.target.value))} />
          </div>
        </div>

        {total > 0 && (
          <div className="total-preview">
            Total: <strong>{formatCOP(total)}</strong>
          </div>
        )}

        <div className="campo-grupo">
          <label className="campo-label">CUFE (opcional)</label>
          <input className="campo-input" type="text" placeholder="Ej. 96 caracteres hexadecimales"
            value={cufe} onChange={e => setCufe(e.target.value)} />
          <span className="campo-hint">Solo si la factura ya fue validada previamente ante la DIAN</span>
        </div>

        <button className="btn-auth-primario" onClick={guardar} disabled={cargando}>
          {cargando ? 'Guardando...' : '✓ Guardar Factura'}
        </button>
      </div>
    </div>
  )
}
